import{_ as t,o as n,c as o,a2 as s}from"./chunks/framework.Bg-Zxr5O.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/String-Functions.md","filePath":"manual-zh/String-Functions.md","lastUpdated":1785684581000}'),r={name:"manual-zh/String-Functions.md"};function g(d,e,a,p,c,i){return n(),o("div",null,[...e[0]||(e[0]=[s('<h4 id="_7-7-7-字符串函数" tabindex="-1">7.7.7 字符串函数 <a class="header-anchor" href="#_7-7-7-字符串函数" aria-label="Permalink to &quot;7.7.7 字符串函数&quot;">​</a></h4><p>字符串函数接受不同类型的参数并返回不同类型的结果。</p><p>函数：__<strong>CONCAT</strong> <em>( string, string[, …])</em></p><p>返回一个由各个字符串依次连接而成的字符串。<code>CONCAT(&quot;abc&quot;, &quot;def&quot;, &quot;ghi&quot;)</code> 的值为 <code>&quot;abcdefghi&quot;</code>。结果字符串会被截断至最多 32767 字节。</p><p>函数：<strong><strong>INDEX</strong> <em>( haystack, needle)</em> 函数：</strong><strong>RINDEX</strong> <em>( haystack, needle)</em></p><p>返回一个正整数，表示 needle 在 haystack 中首次（对 <code>INDEX</code>）或最后（对 <code>RINDEX</code>）出现的位置。若 haystack 不包含 needle，则返回 0。若 needle 为空字符串，则返回 1。</p><p>函数：<strong><strong>INDEX</strong> <em>( haystack, needles, needle_len)</em> 函数：</strong><strong>RINDEX</strong> <em>( haystack, needle, needle_len)</em></p><p>将 needles 划分为多个长度均为 needle_len 的 needle，needle_len 必须是能整除 needles 长度的正整数。在 haystack 中搜索每个 needle 的出现位置，并返回其首次（对 <code>INDEX</code>）或最后（对 <code>RINDEX</code>）出现的字节下标。若 haystack 不包含任何 needle，或 needles 为空字符串，则返回 0。</p><p>函数：__<strong>LENGTH</strong> <em>( string)</em></p><p>返回 string 中的字节数。</p><p>函数：__<strong>LOWER</strong> <em>( string)</em></p><p>返回一个与 string 相同的字符串，但所有大写字母改为小写字母。“大写”和“小写”的定义取决于系统。</p><p>函数：<strong><strong>LPAD</strong> <em>( string, length[, padding])</em> 函数：</strong><strong>RPAD</strong> <em>( string, length[, padding])</em></p><p>若 string 长度至少为 length 字节，这些函数返回未改变的 string。否则，它们在 string 的左侧（对 <code>LPAD</code>）或右侧（对 <code>RPAD</code>）填充 padding 至 length 字节。若 length 缺失或大于 32767，这些函数报告错误并返回未改变的 string。</p><p>padding 参数不可为空字符串；若未指定，则默认为空格。若其长度不能恰好填满所需填充空间，返回的字符串将短于 length。</p><p>函数：<strong><strong>LTRIM</strong> <em>( string[, padding])</em> 函数：</strong><strong>RTRIM</strong> <em>( string[, padding])</em></p><p>这些函数返回移除前导（对 <code>LTRIM</code>）或尾随（对 <code>RTRIM</code>）padding 副本后的 string。若省略 padding，这些函数移除空格（但不包括制表符或其他空白字符）。若 padding 为空字符串，这些函数返回未改变的 string。</p><p>函数：__<strong>NUMBER</strong> <em>( string, format)</em></p><p>返回将 string 按格式说明符 format 解释后得到的数值。若格式宽度 w 小于 string 的长度，则只使用 string 的前 w 字节，例如 <code>NUMBER(&quot;123&quot;, F3.0)</code> 与 <code>NUMBER(&quot;1234&quot;, F3.0)</code> 的值均为 123。若 w 大于 string 的长度，则视为已用空格右填充。若 string 不符合 format 的正确格式，则返回系统缺失值。</p><p>函数：__<strong>REPLACE</strong> <em>( haystack, needle, replacement[, n])</em></p><p>返回将 haystack 中 needle 的实例替换为 replacement 后的字符串。若指定非负整数 n，则限制最大替换次数；否则替换所有 needle 实例。</p><p>函数：__<strong>STRING</strong> <em>( number, format)</em></p><p>返回对应于 number、且按格式说明符 format 给出的格式的字符串。例如，<code>STRING(123.56, F5.1)</code> 的值为 <code>&quot;123.6&quot;</code>。</p><p>函数：__<strong>STRUNC</strong> <em>( string, n)</em></p><p>返回移除尾部空格（但不包括制表符或其他空白字符）后、且被截断至最多 n 字节的 string。若 n 为零或负数，返回空字符串；若 n 缺失，返回未改变的 string。</p><p>函数：__<strong>SUBSTR</strong> <em>( string, start)</em></p><p>返回从位置 start 起到末尾的 string 值组成的字符串。若 start 为系统缺失值、小于 1 或大于 string 长度，返回空字符串。</p><p>函数：__<strong>SUBSTR</strong> <em>( string, start, count)</em></p><p>返回从位置 start 开始、长度为 count 字节的 string 子串。若 start 或 count 为系统缺失值、start 小于 1 或大于 string 的字节数、或 count 小于 1，返回空字符串。若 start + count - 1 大于 string 的字节数，返回短于 count 字节的字符串。示例：<code>SUBSTR(&quot;abcdefg&quot;, 3, 2)</code> 的值为 <code>&quot;cd&quot;</code>；<code>SUBSTR(&quot;nonsense&quot;, 4, 10)</code> 的值为 <code>&quot;sense&quot;</code>。</p><p>函数：__<strong>UPCASE</strong> <em>( string)</em></p><p>返回将小写字母改为大写字母的 string。</p>',31)])])}const _=t(r,[["render",g]]);export{l as __pageData,_ as default};
